// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(0xdead));

        // Transfer ownership to 'caller' via the owner (which is the deployer, address(this))
        c.transferOwnership(caller);

        // Now 'caller' accepts ownership
        vm.prank(caller);
        c.acceptOwnership();

        // After acceptance, the owner should be 'caller'
        assertTrue(c.owner() == caller);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(c) && caller != address(0));

        // Get current owner (reference returns real owner, mutant returns address(0))
        address currentOwner = c.owner();
        vm.assume(caller != currentOwner);

        // Try to acceptOwnership as a non-owner
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("acceptOwnership()"));

        // The rule: caller cannot accept ownership unless they are the pending owner
        // But pending owner is only set via transferOwnership (which owner hasn't done)
        // So the call should always revert
        assertTrue(!success);
    }
}

