pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        vm.assume(newOwner != address(0) && newOwner != address(c));
        c.initialize(0, 0, "test", address(0x1234567890123456789012345678901234567890));

        // Transfer ownership to newOwner
        c.transferOwnership(newOwner);

        // newOwner accepts ownership
        vm.prank(newOwner);
        c.acceptOwnership();

        // After ownership transfer, paused should return false (no pause was ever called)
        assertTrue(c.paused() == false, "paused() should be false");
    }
}

