pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(bool shouldPauseBeforeAccept) public {
        // Setup: if true, pause before acceptOwnership; else unpause (default is unpaused)
        if (shouldPauseBeforeAccept) {
            c.pause(); // pause() is external, onlyOwner works because setUp deploys without owner transfer
            vm.prank(c.owner());
            c.pause();
        } else {
            // already unpaused
        }

        // acceptOwnership will revert if msg.sender is not pendingOwner
        // After deploy, owner is address(this) (the test contract). We need to transfer ownership to a random address then accept.
        address newOwner = address(0x1234);
        vm.prank(c.owner());
        c.transferOwnership(newOwner);
        vm.prank(newOwner);
        c.acceptOwnership();

        // After accepting ownership, the paused state should be as expected
        bool expectedPaused = shouldPauseBeforeAccept;
        assertTrue(expectedPaused == c.paused());
    }
}

