pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 tokenId) public {
        // Ensure the contract is initialized and we have a default royalty configuration
        // The reference returns royaltyBPS = 500 for unset tokens; the bug returns 0.
        // We need to initialize the contract to enter a state where getRoyalties can be called.
        // The initialize function requires the caller to be the contract itself (since msg.sender becomes phiFactoryContract).
        // To avoid complexity, we can directly set up the state via the constructor? No, C has _disableInitializers.
        // Instead, we'll call initialize via the proxy pattern? No, C is not a proxy here.
        // We can deploy C as an upgradeable proxy? The test uses new C() directly, so it's the implementation.
        // The implementation has _disableInitializers, but we can still call initialize because it checks initializer modifier.
        // The initializer modifier checks if the contract is already initialized; it will revert if called twice.
        // So we need to call initialize once during setUp.
        // However, the initialize function expects a protocolFeeDestination address; we can pass any non-zero address.
        // Let's adjust setUp to call initialize.
        // But the test template doesn't include that; we can add it in setUp.
        // Since the instructions say setUp must be exactly: function setUp() public { c = new C(); }
        // That is a hard requirement. So we must work with the uninitialized contract.
        // In an uninitialized state, getRoyalties will revert with NotInitialized().
        // So we need to initialize it. But we cannot modify setUp. So we must initialize inside the test.
        // We can call c.initialize() directly, but it's external and requires the initializer modifier.
        // The initializer modifier will succeed on the first call even if deployed directly.
        // So we can do: c.initialize(0, 0, "", address(this));
        // But that changes the state. The fuzz parameters should drive the test.
        // Let's initialize with arbitrary values.
        // We'll use vm.assume to ensure tokenId is realistic (e.g., not too large).
        vm.assume(tokenId < 10000);
        // Initialize the contract
        c.initialize(1, 1, "test", address(0x1234));
        // Now getRoyalties should not revert. For an unset token, reference returns (500, royaltyRecipient),
        // bug returns (0, address(0)).
        ICreatorRoyaltiesControl.RoyaltyConfiguration memory config = c.getRoyalties(tokenId);
        // General rule: royaltyBPS should be 500 if not explicitly set (since default is 500).
        // The reference contract: after initializeRoyalties, default royaltyRecipient is set to protocolFeeDestination.
        // In the reference, if tokenId has no explicit royalty, getRoyalties returns (500, royaltyRecipient).
        // The bug returns (0, address(0)). So we assert royaltyBPS != 0 (specifically 500).
        // But we cannot assume royaltyRecipient is non-zero because we passed address(0x1234) which is non-zero.
        // So the rule: when tokenId's royalty is not set, royaltyBPS should be > 0.
        assertTrue(config.royaltyBPS > 0, "royaltyBPS should be > 0 for unset token");
    }
}

