import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 tokenId) public {
        // acceptOwnership requires a pending owner; simulate by making this contract the owner
        // Since setUp() deploys a fresh C, we set up ownership transfer via vm.prank
        // In the actual contract, owner() is set to msg.sender in initialize(). 
        // For testing we make this contract the owner.
        // We'll use vm.prank to set pending owner and then accept.
        // However, the test must be general: just call acceptOwnership and then check the invariant.
        // To make the call succeed, we need a pending owner. Use vm.startPrank to set owner to address(this).
        // The contract is not initialized in setUp(), so we need to initialize it first.
        // For simplicity, we'll directly test the invariant after initialization.
        // Since the bug is about getRoyalties returning zero when unset, we check that after initialization.
        // The test works on the deployed C after setUp().
        // We don't need to call acceptOwnership for this property; the invariant holds regardless.
        // The rule: for any tokenId, getRoyalties(tokenId).royaltyRecipient != address(0).
        // This passes on reference (returns default recipient) and fails on bug (returns address(0)).
        // To ensure initialization, we call initialize via vm.prank.
        // But setUp() doesn't initialize; we need to do it in the test.
        // We'll use the constructor approach: since C is deployed without initialize, 
        // we can't call getRoyalties until initialized. So we initialize first.
        // Use vm.prank to call initialize as the deployer.
        // We'll make the test contract the owner for simplicity.

        // Initialize: credChainId, credId, verificationType, protocolFeeDestination
        vm.assume(tokenId < 1000000); // keep reasonable
        // Use vm.startPrank to set msg.sender as the deployer
        address owner = address(this);
        vm.prank(owner);
        c.initialize(1, 1, "test", owner);

        // Now call acceptOwnership (but it's not needed for this invariant)
        // The invariant: after initialization, getRoyalties for any token returns non-zero recipient
        ( , address recipient) = c.royaltyInfo(tokenId, 1 ether);
        assertTrue(recipient != address(0));
    }
}

