        // We use try/catch because acceptOwnership may revert if caller is not pending owner
        bool reverted = false;
        try c.acceptOwnership() {
            // If successful, the new owner should be caller
            assertEq(c.owner(), caller);
        } catch {
            reverted = true;
        }

        // The general rule: acceptOwnership should succeed if and only if caller equals pending owner
        // pending owner is newOwner (unless the buggy version returns address(0))
        // But we can only make an assertion about the return values, not internal state
        // So: after calling acceptOwnership (whether it reverts or not), we check the new owner
        // The rule: if acceptOwnership did not revert, then the owner must have changed to caller
        // If it reverted but caller was actually the pending owner, that's a bug (but we can't check pending easily)
        // Better: do two branches: call as pending owner, then as someone else
    }

    // More precise fuzz: directly test that pendingOwner returns the value that acceptOwnership uses
    function testFuzz_acceptOwnership(address caller, address owner, address pendingOwner) public {
        // This test assumes we can transfer ownership to pendingOwner
        vm.assume(owner != address(0));
        vm.assume(pendingOwner != address(0));
        vm.assume(caller != address(0));

        // Transfer to pendingOwner
        vm.prank(c.owner());
        c.transferOwnership(pendingOwner);

        // Get the pending owner
        address p = c.pendingOwner();

        // Now try to accept as caller
        vm.prank(caller);
        bool reverted = false;
        try c.acceptOwnership() {
            // if success, owner must be caller
            assertEq(c.owner(), caller);
        } catch {
            reverted = true;
        }

        // The rule: if pendingOwner is caller, then accept should succeed (not revert) and set owner to caller
        // If pendingOwner is not caller, then accept should revert
        // But we can't directly observe pendingOwner after the call? No, pendingOwner is public.
        // Actually we can read it after
        address pAfter = c.pendingOwner();

        // General rule: 
        // If acceptOwnership succeeds (no revert), then:
        //   - the new owner is caller
        //   - pendingOwner becomes zero
        // If acceptOwnership reverts, then:
        //   - owner unchanged
        //   - pendingOwner unchanged

        if (!reverted) {
            // Success case: caller must have been the pending owner
            // But we can't assert that without internal info; however we can assert the effects
            assertEq(c.owner(), caller);
            assertEq(c.pendingOwner(), address(0), "after accept, pending should be zero");
        } else {
            // Revert case: caller was not the pending owner
            assertEq(c.owner(), owner, "owner should be unchanged");
            assertEq(c.pendingOwner(), pendingOwner, "pending should be unchanged");
        }
    }

    // The above covers the invariant: acceptOwnership's behavior depends on pendingOwner
    // In the buggy version, pendingOwner always returns address(0), so the rule breaks.
}

